mapper.select:
SELECT notice_id AS id, title, content, summary, publisher, publisher_type, publisher_dept,
       top_flag, status, street_name, is_read, read_time, create_time
FROM street_notice
WHERE street_name = #{streetName} AND status = 1
AND publisher_type = #{publisherType}
AND publisher_dept = #{publisherDept}

    AND (title LIKE CONCAT('%', #{keyword}, '%') OR content LIKE CONCAT('%', #{keyword}, '%') OR summary LIKE CONCAT('%', #{keyword}, '%'))

AND create_time >= #{startTime}
AND create_time < #{endTime}
ORDER BY top_flag DESC, create_time DESC
LIMIT #{offset}, #{size}

SELECT COUNT(1)
FROM street_notice
WHERE street_name = #{streetName} AND status = 1
AND publisher_type = #{publisherType}
AND publisher_dept = #{publisherDept}

    AND (title LIKE CONCAT('%', #{keyword}, '%') OR content LIKE CONCAT('%', #{keyword}, '%') OR summary LIKE CONCAT('%', #{keyword}, '%'))

AND create_time >= #{startTime}
AND create_time < #{endTime}

mapper.update:
UPDATE street_notice
SET title = #{title}, content = #{content}, summary = #{summary}
WHERE notice_id = #{noticeId}
